"""Presentation theme for PAED AlphaLens."""

CSS = ":root {--ink:#172437;--muted:#65758a;--navy:#12263b;--teal:#087e82;--line:#dfe8ee;}\n.stApp {background:linear-gradient(180deg,#f5f8fa 0%,#ffffff 60%); color:var(--ink);}\n.block-container {max-width:1220px; padding-top:2rem; padding-bottom:4rem;}\nh1,h2,h3 {font-family:Inter,\"Segoe UI\",sans-serif!important;letter-spacing:-.035em;color:#172437!important;}\nh1 {font-size:3rem!important; font-weight:720!important;} h2 {font-weight:650!important;}\np,div,label {font-family:Inter,\"Segoe UI\",sans-serif;}\ndiv[data-testid=\"stMetric\"] {background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px 20px;box-shadow:0 5px 22px rgba(20,40,55,.045);}\ndiv[data-testid=\"stMetricLabel\"] {color:var(--muted);}\ndiv[data-testid=\"stMetricValue\"] {color:#172437;font-weight:700;}\n.stButton>button[kind=\"primary\"],.stDownloadButton>button {border-radius:12px;border:1px solid #15374c; background:#15374c;color:white;padding:.62rem 1.15rem;font-weight:600;}\n.stButton>button[kind=\"primary\"]:hover,.stDownloadButton>button:hover {background:#087e82;border-color:#087e82;color:white;}\nbutton[data-baseweb=\"tab\"] {font-size:.94rem;font-weight:600;padding:.9rem .85rem;}\ndiv[data-testid=\"stAlert\"] {border-radius:12px;}\ndiv[data-testid=\"stDataFrame\"],div[data-testid=\"stPlotlyChart\"] {border-radius:14px;}\n.al-hero {background:#12263b;color:#fff;border-radius:22px;padding:36px 38px;margin-bottom:25px;box-shadow:0 14px 35px rgba(18,38,59,.12);}\n.al-eyebrow {font-size:11px;letter-spacing:.17em;text-transform:uppercase;color:#94d6d0;font-weight:700;margin-bottom:14px;}\n.al-hero-title {font-size:46px;letter-spacing:-.04em;font-weight:740;line-height:1.05;margin-bottom:10px;color:#fff!important;}\n.al-hero-sub {color:#d5e5ef;font-size:18px;max-width:690px;margin-bottom:18px;}\n.al-pill {display:inline-block;border:1px solid #547184;border-radius:40px;padding:7px 12px;font-size:12px;color:#d9ebf4;margin-right:7px;margin-top:5px;}\n.al-intro {color:#586a7c;font-size:15px;max-width:900px;margin-bottom:18px;}\n.al-kicker {font-size:12px;font-weight:750;letter-spacing:.09em;color:#087e82;text-transform:uppercase;margin-top:4px;}\n.al-note {background:#eef7f6;border-left:3px solid #087e82;padding:14px 17px;border-radius:0 11px 11px 0;color:#244e55;margin:14px 0 20px 0;}\n.al-warning {background:#fff6ed;border-left:3px solid #ba7431;padding:14px 17px;border-radius:0 11px 11px 0;color:#6d4828;margin:14px 0 20px 0;}\n"
CSS += "\n/* Responsive, low-noise institutional finish */\n@media (max-width: 720px) {\n .block-container {padding:1rem .85rem 3rem!important;}\n .al-hero {padding:24px 22px;border-radius:16px;}\n .al-hero-title {font-size:34px!important;}\n .al-hero-sub {font-size:15px;}\n div[data-testid=\"stMetric\"] {padding:12px;}\n}\nbutton:focus-visible, a:focus-visible {outline:3px solid #087e82!important;outline-offset:2px;}\n.stButton>button {border-radius:11px;transition:background-color .16s ease,border-color .16s ease;}\ndiv[data-testid=\"stExpander\"] {border:1px solid #e1e9ed;border-radius:13px;background:#fff;}\ndiv[data-testid=\"stVerticalBlockBorderWrapper\"] {border-radius:14px;}\n.al-hero-title,.al-hero-sub,.al-eyebrow {position:relative;z-index:1;}\n"
